/**
 * Rend une icone SVG depuis la map $icons.
 */
function renderIcon(string $name, array $iconMap): string
{
    $path = $iconMap[$name] ?? '';
    return '<svg class="w-5 h-5 shrink-0" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor">' . $path . '</svg>';
}
